-- 2.2M SBA 7(a) and 504 loans since 1991 -- borrower name, address, lender, and amount, released under FOIA.
-- Auto-generated by scripts/gen_evidence_pages.py: 2,174,502 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("ASOFDATE") as year, count(*) as records
from THE_LIBRARY.GOVERNMENT_SPENDING.SBA_SMALL_BUSINESS_LOANS
where "ASOFDATE" is not null
group by 1
order by 1
